-- ========================================================
-- E-Disiplin ASN - Database Schema
-- PostgreSQL
-- ========================================================
--
-- Database harus dibuat dulu sebelum skrip ini dijalankan, contoh:
--   CREATE DATABASE edisiplin_asn;
-- (Docker: image postgres dengan POSTGRES_DB=edisiplin_asn)
--
-- Skrip ini idempotent (boleh dijalankan berulang — dipakai oleh `npm run seed`).
--
-- Catatan perubahan dari versi MySQL:
--   * AUTO_INCREMENT  -> GENERATED BY DEFAULT AS IDENTITY
--   * ENUM            -> VARCHAR + CHECK (skrip tetap bisa dijalankan ulang)
--   * ON UPDATE CURRENT_TIMESTAMP -> trigger set_updated_at()
--   * backtick        -> tanpa quote (identifier memakai huruf kecil semua)
--   * TIMESTAMP       -> TIMESTAMPTZ (sesi memakai zona Asia/Jakarta)
--   * ENGINE=InnoDB   -> dihapus (PostgreSQL tidak punya storage engine)

-- Trigger pembantu untuk kolom updated_at
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 1. Organizational Units
CREATE TABLE IF NOT EXISTS org_units (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  head_name VARCHAR(150),
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- 2. Users (System users who can log in)
CREATE TABLE IF NOT EXISTS users (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nip VARCHAR(30) NOT NULL UNIQUE,
  name VARCHAR(150) NOT NULL,
  email VARCHAR(150) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role VARCHAR(20) NOT NULL DEFAULT 'pegawai'
    CHECK (role IN ('admin', 'atasan', 'pemeriksa', 'bkpsdm', 'pegawai', 'inspektorat')),
  unit_id INT,
  position VARCHAR(150),
  avatar VARCHAR(255),
  is_active BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (unit_id) REFERENCES org_units(id) ON DELETE SET NULL
);

DROP TRIGGER IF EXISTS trg_users_updated_at ON users;
CREATE TRIGGER trg_users_updated_at BEFORE UPDATE ON users
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 3. Employees (Master data of all ASN)
CREATE TABLE IF NOT EXISTS employees (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nip VARCHAR(30) NOT NULL UNIQUE,
  name VARCHAR(150) NOT NULL,
  unit_id INT,
  position VARCHAR(150),
  status VARCHAR(20) DEFAULT 'active'
    CHECK (status IS NULL OR status IN ('active', 'inactive', 'suspended', 'pension')),
  type VARCHAR(10) NOT NULL DEFAULT 'PNS'
    CHECK (type IN ('PNS', 'PPPK')),
  rank_grade VARCHAR(50),
  join_date DATE,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (unit_id) REFERENCES org_units(id) ON DELETE SET NULL
);

-- 4. Attendance
CREATE TABLE IF NOT EXISTS attendance (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  employee_id INT NOT NULL,
  date DATE NOT NULL,
  time_in TIME,
  time_out TIME,
  status VARCHAR(20) DEFAULT 'hadir'
    CHECK (status IS NULL OR status IN ('hadir', 'terlambat', 'ijin', 'sakit', 'alpa')),
  note VARCHAR(255),
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE,
  CONSTRAINT uniq_emp_date UNIQUE (employee_id, date)
);

-- 5. Reports (Laporan Pelanggaran)
CREATE TABLE IF NOT EXISTS reports (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  report_no VARCHAR(50) NOT NULL UNIQUE,
  reporter_id INT,
  reported_employee_id INT NOT NULL,
  category VARCHAR(40) NOT NULL
    CHECK (category IN ('kehadiran', 'kinerja', 'kode_etik', 'pidana', 'penyalahgunaan_wewenang', 'lainnya')),
  title VARCHAR(255) NOT NULL,
  description TEXT NOT NULL,
  incident_date DATE,
  incident_location VARCHAR(255),
  priority VARCHAR(20) DEFAULT 'sedang'
    CHECK (priority IS NULL OR priority IN ('rendah', 'sedang', 'tinggi', 'kritis')),
  status VARCHAR(30) DEFAULT 'diajukan'
    CHECK (status IS NULL OR status IN ('draft', 'diajukan', 'diverifikasi', 'ditolak', 'ditingkatkan_ke_kasus')),
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (reporter_id) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (reported_employee_id) REFERENCES employees(id) ON DELETE CASCADE
);

DROP TRIGGER IF EXISTS trg_reports_updated_at ON reports;
CREATE TRIGGER trg_reports_updated_at BEFORE UPDATE ON reports
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 6. Cases (Kasus Disiplin)
CREATE TABLE IF NOT EXISTS cases (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  case_no VARCHAR(50) NOT NULL UNIQUE,
  report_id INT,
  subject_employee_id INT NOT NULL,
  category VARCHAR(100) NOT NULL,
  title VARCHAR(255) NOT NULL,
  description TEXT,
  status VARCHAR(30) DEFAULT 'baru'
    CHECK (status IS NULL OR status IN ('baru', 'penyelidikan', 'pemeriksaan', 'sidang_kode_etik', 'putusan', 'selesai', 'dibatalkan')),
  priority VARCHAR(20) DEFAULT 'sedang'
    CHECK (priority IS NULL OR priority IN ('rendah', 'sedang', 'tinggi', 'kritis')),
  level VARCHAR(20) DEFAULT 'sedang'
    CHECK (level IS NULL OR level IN ('ringan', 'sedang', 'berat')),
  pic_id INT,
  deadline DATE,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (report_id) REFERENCES reports(id) ON DELETE SET NULL,
  FOREIGN KEY (subject_employee_id) REFERENCES employees(id) ON DELETE CASCADE,
  FOREIGN KEY (pic_id) REFERENCES users(id) ON DELETE SET NULL
);

DROP TRIGGER IF EXISTS trg_cases_updated_at ON cases;
CREATE TRIGGER trg_cases_updated_at BEFORE UPDATE ON cases
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 7. Case Timeline
CREATE TABLE IF NOT EXISTS case_timeline (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  case_id INT NOT NULL,
  action VARCHAR(255) NOT NULL,
  actor_id INT,
  type VARCHAR(50) DEFAULT 'status_change',
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (case_id) REFERENCES cases(id) ON DELETE CASCADE,
  FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE SET NULL
);

-- 8. Documents
CREATE TABLE IF NOT EXISTS documents (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  case_id INT,
  report_id INT,
  name VARCHAR(255) NOT NULL,
  original_name VARCHAR(255) NOT NULL,
  file_path VARCHAR(500) NOT NULL,
  file_size INT,
  mime_type VARCHAR(100),
  uploader_id INT,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (case_id) REFERENCES cases(id) ON DELETE CASCADE,
  FOREIGN KEY (report_id) REFERENCES reports(id) ON DELETE CASCADE,
  FOREIGN KEY (uploader_id) REFERENCES users(id) ON DELETE SET NULL
);

-- 9. Examinations (Jadwal & Hasil Pemeriksaan BAP)
CREATE TABLE IF NOT EXISTS examinations (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  exam_no VARCHAR(50) NOT NULL UNIQUE,
  case_id INT NOT NULL,
  subject_employee_id INT NOT NULL,
  examiner_id INT NOT NULL,
  schedule_time TIMESTAMPTZ NOT NULL,
  venue VARCHAR(255) NOT NULL,
  status VARCHAR(20) DEFAULT 'terjadwal'
    CHECK (status IS NULL OR status IN ('terjadwal', 'berlangsung', 'selesai', 'dibatalkan', 'ditunda')),
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (case_id) REFERENCES cases(id) ON DELETE CASCADE,
  FOREIGN KEY (subject_employee_id) REFERENCES employees(id) ON DELETE CASCADE,
  FOREIGN KEY (examiner_id) REFERENCES users(id) ON DELETE CASCADE
);

-- 10. Decisions (Surat Keputusan Hukuman Disiplin)
CREATE TABLE IF NOT EXISTS decisions (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sk_no VARCHAR(100) NOT NULL UNIQUE,
  case_id INT NOT NULL,
  employee_id INT NOT NULL,
  penalty_type VARCHAR(150) NOT NULL,
  penalty_level VARCHAR(20) NOT NULL
    CHECK (penalty_level IN ('ringan', 'sedang', 'berat')),
  effective_date DATE NOT NULL,
  issued_by_id INT,
  status VARCHAR(20) DEFAULT 'ditetapkan'
    CHECK (status IS NULL OR status IN ('draft', 'ditetapkan', 'banding', 'berlaku', 'dicabut')),
  file_path VARCHAR(500),
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (case_id) REFERENCES cases(id) ON DELETE CASCADE,
  FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE,
  FOREIGN KEY (issued_by_id) REFERENCES users(id) ON DELETE SET NULL
);

-- 11. Audit Logs
CREATE TABLE IF NOT EXISTS audit_logs (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id INT,
  user_name VARCHAR(150),
  action VARCHAR(100) NOT NULL,
  detail TEXT,
  module VARCHAR(100) NOT NULL,
  ip_address VARCHAR(50),
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- 12. Refresh Tokens
CREATE TABLE IF NOT EXISTS refresh_tokens (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id INT NOT NULL,
  token VARCHAR(500) NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
